47: 
48:     let strategy = if let Some(dict_path) = password_dictionary {
49:         let path = Path::new(&dict_path);
50:         PasswordFile(path.to_path_buf())
51:     } else if let Some(mask_pattern) = mask {
52:         let mask = parse_mask(&mask_pattern, &custom_charsets)?;
53:         MaskGenPasswords { mask }
54:     } else {
55:         let charset = charset_from_choice(&charset_choice)?;
56:         GenPasswords {
57:             charset,
58:             min_password_len,
59:             max_password_len,
60:             starting_password,
61:         }
62:     };
63: 
64:     // use physical cores by default to avoid issues with hyper-threading
65:     let workers = workers.unwrap_or_else(num_cpus::get_physical);
66:     let start_time = std::time::Instant::now();
67: 
68:     // stop signals to shut down threads
69:     let stop_signal = Arc::new(AtomicBool::new(false));
70: 
71:     // Intercept Ctrl-C signal to stop workers manually
72:     let stop_signal_interrupt = stop_signal.clone();
73:     ctrlc::set_handler(move || stop_signal_interrupt.store(true, Ordering::Relaxed))
